<?php
 namespace Pterodactyl\Services\Dezerx\Palworld; use Pterodactyl\Services\Dezerx\Addons; class PalworldMods { public const DEFAULT_DIRECTORY = 'Pal/Content/Paks/~mods'; public const DEFAULT_EXTENSIONS = '.pak,.ucas,.utoc,.zip,.dll,.lua'; public const DISABLED_SUFFIX = '.disabled'; public static function directory(): string { $raw = trim((string) (Addons::get(Addons::PALWORLD_MOD_MANAGER)['palworld_directory'] ?? '')); $clean = trim(str_replace('\\', '/', $raw), '/'); if ($clean === '' || str_contains($clean, '..')) { return self::DEFAULT_DIRECTORY; } return $clean; } public static function extensions(): array { $raw = trim((string) (Addons::get(Addons::PALWORLD_MOD_MANAGER)['palworld_extensions'] ?? '')); if ($raw === '') { $raw = self::DEFAULT_EXTENSIONS; } $out = []; foreach (explode(',', $raw) as $piece) { $piece = mb_strtolower(trim($piece)); if ($piece === '') { continue; } $out[] = str_starts_with($piece, '.') ? $piece : '.' . $piece; } return $out === [] ? explode(',', self::DEFAULT_EXTENSIONS) : array_values(array_unique($out)); } public static function isMod(string $file): bool { $lower = mb_strtolower($file); if (str_ends_with($lower, self::DISABLED_SUFFIX)) { $lower = mb_substr($lower, 0, -mb_strlen(self::DISABLED_SUFFIX)); } foreach (self::extensions() as $extension) { if (str_ends_with($lower, $extension)) { return true; } } return false; } public static function safeName(string $file): ?string { $file = trim($file); if ($file === '' || str_contains($file, '/') || str_contains($file, '\\') || str_contains($file, '..')) { return null; } return self::isMod($file) ? $file : null; } } 